svg.script:
//!export-start
let _pn_level = 50;
let _pn_max = 100;
let _ps_trend = 'stable';
let _ps_fluid = 'fresh-water';
let _ps_tag = 'T-101';
//!export-end

var __busyUntil = 0;

function toBool(v) {
    if (v === true || v === 1) return true;
    var s = String(v).toLowerCase();
    return s === 'true' || s === '1' || s === 'on';
}

function toNum(v) {
    var n = parseFloat(v);
    return isNaN(n) ? 0 : n;
}

function apply() {
    var preview = document.getElementById('ob_preview');
    if (preview && preview.parentNode) { preview.parentNode.removeChild(preview); }
    var el = document.getElementById('ob_el');
    if (!el) return;
    el.value = toNum(_pn_level);
    el.max = toNum(_pn_max);
    el.trend = String(_ps_trend);
    el.tag = String(_ps_tag);
    el.style.setProperty('--automation-medium-fuel', 'var(--automation-medium-' + String(_ps_fluid) + ')');
}

function putValue(id, value) {
    if (id === '_pn_level') { _pn_level = toNum(value); }
    if (id === '_pn_max') { _pn_max = toNum(value); }
    if (id === '_ps_trend') { _ps_trend = String(value); }
    if (id === '_ps_fluid') { _ps_fluid = String(value); }
    if (id === '_ps_tag') { _ps_tag = String(value); }
    apply();
}

function postValue(id, value) {
    // replaced at runtime: writes value to the tag bound to "id"
}

apply();
